-- Store cosmetics and Miles. Two currencies on one ledger (credits from votes, Miles bought as
-- Discord consumable SKUs, paid once per entitlement), per-user equipped cosmetics (one per slot),
-- store-wide settings (the credits-per-Mile rate) and a starter cosmetics catalog.
ALTER TABLE `store_credit_ledger` ADD `currency` text DEFAULT 'credits' NOT NULL;
--> statement-breakpoint
ALTER TABLE `store_credit_ledger` ADD `entitlement_id` text;
--> statement-breakpoint
ALTER TABLE `store_credit_ledger` ADD `note` text;
--> statement-breakpoint
CREATE UNIQUE INDEX `store_credit_ledger_entitlement` ON `store_credit_ledger` (`entitlement_id`);
--> statement-breakpoint
CREATE INDEX `store_credit_ledger_user_currency` ON `store_credit_ledger` (`user_id`, `currency`);
--> statement-breakpoint
ALTER TABLE `store_products` ADD `price_miles` integer;
--> statement-breakpoint
DROP INDEX IF EXISTS `store_entitlements_ledger`;
--> statement-breakpoint
CREATE INDEX `store_entitlements_ledger` ON `store_entitlements` (`ledger_id`);
--> statement-breakpoint
CREATE TABLE `store_settings` (
	`id` integer PRIMARY KEY NOT NULL,
	`credits_per_mile` real DEFAULT 2 NOT NULL,
	`miles_entitlement_cursor` text,
	`updated_at` integer,
	`updated_by` text
);
